// 20 ниш соцсетей × 10 prompt-паков на каждую.
// Используется на /generate как альтернатива дефолтным AVATAR_STYLES.
// Формат promptStyle — короткое описание ИЗМЕНЯЕМОГО (wardrobe + setting + lighting),
// которое идёт после "NEW SETTING:" в edit-mode шаблоне (см. buildAvatarPrompt).

export type NichePrompt = {
  slug: string;       // уникален в рамках ниши: 'beauty-skincare-01'
  label: string;      // 'Glass Skin Editorial'
  description: string;// короткий ru-сабтайтл для UI
  promptStyle: string;
  allowRigidPose?: boolean;
};

export type Niche = {
  slug: string;
  label: string;
  description: string;
  prompts: NichePrompt[];
};

const N = (
  base: string,
  items: Array<Omit<NichePrompt, 'slug'> & { id: string }>,
): NichePrompt[] => items.map((it) => ({ slug: `${base}-${it.id}`, ...it }));

