export function nicheBySlug(slug: string): Niche | null {
  return NICHES.find((n) => n.slug === slug) ?? null;
}

export function nichePromptBySlug(nicheSlug: string, promptSlug: string): NichePrompt | null {
  const niche = nicheBySlug(nicheSlug);
  if (!niche) return null;
  return niche.prompts.find((p) => p.slug === promptSlug) ?? null;
}
